type lane=Mechanical|Ownership|Metadata
type package=Encoder|Pass_descriptor|Sample_attachment|Attachment_array|Type_metadata
type item={id:string;lane:lane;package:package;operation:string;tests:string list}
let mechanical_ids=["method:-[MTLAccelerationStructurePassSampleBufferAttachmentDescriptor endOfEncoderSampleIndex]";"method:-[MTLAccelerationStructurePassSampleBufferAttachmentDescriptor setEndOfEncoderSampleIndex:]";"method:-[MTLAccelerationStructurePassSampleBufferAttachmentDescriptor setStartOfEncoderSampleIndex:]";"method:-[MTLAccelerationStructurePassSampleBufferAttachmentDescriptor startOfEncoderSampleIndex]";"property:MTLAccelerationStructurePassSampleBufferAttachmentDescriptor:endOfEncoderSampleIndex";"property:MTLAccelerationStructurePassSampleBufferAttachmentDescriptor:startOfEncoderSampleIndex"]
let contains s n=let l=String.length n in let rec f i=i+l<=String.length s&&(String.sub s i l=n||f(i+1))in f 0
let classify~kind id=let lane=if List.mem id mechanical_ids then Mechanical else if kind="method"||kind="property"then Ownership else Metadata in let package,operation,tests=if lane=Metadata then Type_metadata,"Metal.Acceleration command opaque descriptor types",["public type provenance"]else if contains id "AttachmentDescriptorArray"then Attachment_array,"Metal.Acceleration_pass.attachments",["index bounds";"retained replacement"]else if contains id "SampleBufferAttachmentDescriptor"then Sample_attachment,"Metal.Acceleration_pass.Sample_attachment",["sample-buffer identity";"index/order validation";"destroy order"]else if contains id "PassDescriptor"then Pass_descriptor,"Metal.Acceleration_pass.Descriptor",["attachment graph snapshot";"mutation-after-create retention"]else Encoder,"Metal.Acceleration_encoder build/refit/copy/write",["same-device and exact handle kind";"range/size validation";"completion retention";"no-handle-delta rejection"]in{id;lane;package;operation;tests}
let validate items=let count f=List.length(List.filter f items)in if List.length items<>32||count(fun x->x.lane=Mechanical)<>6||count(fun x->x.lane=Ownership)<>22||count(fun x->x.lane=Metadata)<>4||List.map(fun p->count(fun x->x.package=p))[Encoder;Pass_descriptor;Sample_attachment;Attachment_array;Type_metadata]<>[14;3;9;2;4]then failwith"AccelerationCommand32 handoff drift"
